/**
 * MessageActions — 消息操作栏（增强版）。
 *
 * 参考 deer-flow 的 👍/👎 toggle + dify 的分组布局：
 * - 用户消息 hover 显示：时间戳 | 复制
 * - AI 回复 hover 显示：时间戳 | 复制 收藏 转发 | 👍 👎 反馈 | 重新生成
 * - 👍/👎 支持 toggle（再次点击取消）
 * - 踩时弹出 FeedbackModal
 */
import { useCallback, useState } from 'react'
import { Check, Copy, RefreshCw, ThumbsUp, ThumbsDown, Bookmark, Share2, MessageSquare } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Message } from '@/lib/api'

interface MessageActionsProps {
  content: string
  role: 'user' | 'assistant'
  timestamp?: string
  messageId?: number
  onRegenerate?: () => void
  // 新增
  feedback?: Message['feedback']
  onFeedback?: (rating: 'like' | 'dislike', comment?: string) => void
  onDeleteFeedback?: () => void
  isBookmarked?: boolean
  onBookmark?: () => void
  onFeedbackOpen?: () => void
  elapsedMs?: number
}

export function MessageActions({
  content,
  role,
  timestamp,
  messageId,
  onRegenerate,
  feedback,
  onFeedback,
  onDeleteFeedback,
  isBookmarked,
  onBookmark,
  onFeedbackOpen,
  elapsedMs,
}: MessageActionsProps) {
  const [copied, setCopied] = useState(false)

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(content)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    } catch {
      // fallback
      const ta = document.createElement('textarea')
      ta.value = content
      document.body.appendChild(ta)
      ta.select()
      document.execCommand('copy')
      document.body.removeChild(ta)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    }
  }, [content])

  const handleShare = useCallback(async () => {
    try {
      if (navigator.share) {
        await navigator.share({ text: content })
      } else {
        await navigator.clipboard.writeText(content)
      }
    } catch {
      // 用户取消分享
    }
  }, [content])

  const handleLike = useCallback(() => {
    if (feedback?.rating === 'like') {
      onDeleteFeedback?.()
    } else {
      onFeedback?.('like')
    }
  }, [feedback, onFeedback, onDeleteFeedback])

  const handleDislike = useCallback(() => {
    if (feedback?.rating === 'dislike') {
      onDeleteFeedback?.()
    } else {
      onFeedbackOpen?.()
    }
  }, [feedback, onFeedbackOpen, onDeleteFeedback])

  return (
    <div className={cn(
      'flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-150',
      role === 'user' ? 'justify-end' : 'justify-start',
    )}>
      {/* 时间戳 */}
      {timestamp && (
        <span className="px-1 text-[10px] text-muted-foreground/40">
          {new Date(timestamp).toLocaleTimeString('zh-CN', {
            hour: '2-digit',
            minute: '2-digit',
          })}
        </span>
      )}

      {/* 回答耗时 */}
      {elapsedMs != null && (
        <span className="px-1 text-[10px] text-muted-foreground/50 tabular-nums">
          {elapsedMs < 1000 ? `${Math.round(elapsedMs)}ms` : `${(elapsedMs / 1000).toFixed(1)}s`}
        </span>
      )}

      {/* 分隔符 */}
      <span className="text-muted-foreground/20">|</span>

      {/* 复制按钮 */}
      <button
        onClick={handleCopy}
        className="rounded-md p-1 text-muted-foreground/60 hover:bg-accent hover:text-foreground transition-colors"
        title="复制"
      >
        {copied ? (
          <Check className="h-3 w-3 text-green-500" />
        ) : (
          <Copy className="h-3 w-3" />
        )}
      </button>

      {/* AI 回复专属操作 */}
      {role === 'assistant' && messageId && (
        <>
          {/* 收藏 */}
          {onBookmark && (
            <button
              onClick={onBookmark}
              className={cn(
                'rounded-md p-1 transition-colors',
                isBookmarked
                  ? 'text-yellow-500 hover:bg-accent'
                  : 'text-muted-foreground/60 hover:bg-accent hover:text-foreground'
              )}
              title={isBookmarked ? '取消收藏' : '收藏'}
            >
              <Bookmark className={cn('h-3 w-3', isBookmarked && 'fill-current')} />
            </button>
          )}

          {/* 转发 */}
          <button
            onClick={handleShare}
            className="rounded-md p-1 text-muted-foreground/60 hover:bg-accent hover:text-foreground transition-colors"
            title="转发"
          >
            <Share2 className="h-3 w-3" />
          </button>

          {/* 分隔符 */}
          <span className="text-muted-foreground/20">|</span>

          {/* 点赞 */}
          {onFeedback && (
            <button
              onClick={handleLike}
              className={cn(
                'rounded-md p-1 transition-colors',
                feedback?.rating === 'like'
                  ? 'text-green-500 hover:bg-accent'
                  : 'text-muted-foreground/60 hover:bg-accent hover:text-foreground'
              )}
              title="点赞"
            >
              <ThumbsUp className={cn('h-3 w-3', feedback?.rating === 'like' && 'fill-current')} />
            </button>
          )}

          {/* 点踩 */}
          {onFeedback && (
            <button
              onClick={handleDislike}
              className={cn(
                'rounded-md p-1 transition-colors',
                feedback?.rating === 'dislike'
                  ? 'text-red-500 hover:bg-accent'
                  : 'text-muted-foreground/60 hover:bg-accent hover:text-foreground'
              )}
              title="点踩"
            >
              <ThumbsDown className={cn('h-3 w-3', feedback?.rating === 'dislike' && 'fill-current')} />
            </button>
          )}

          {/* 反馈 */}
          {onFeedbackOpen && (
            <button
              onClick={onFeedbackOpen}
              className="rounded-md p-1 text-muted-foreground/60 hover:bg-accent hover:text-foreground transition-colors"
              title="反馈"
            >
              <MessageSquare className="h-3 w-3" />
            </button>
          )}

          {/* 分隔符 */}
          <span className="text-muted-foreground/20">|</span>

          {/* 重新生成 */}
          {onRegenerate && (
            <button
              onClick={onRegenerate}
              className="rounded-md p-1 text-muted-foreground/60 hover:bg-accent hover:text-foreground transition-colors"
              title="重新生成"
            >
              <RefreshCw className="h-3 w-3" />
            </button>
          )}
        </>
      )}
    </div>
  )
}
